<?php require_once __DIR__.'/chart_local.php'; function mailplot(){$r=db_query("SELECT COUNT(*),mail_type.name FROM mail_log,mail_type WHERE date>=DATE_SUB(NOW(),INTERVAL 1 MONTH) AND mail_log.typefk=mail_type.ref GROUP BY mail_type.name ORDER BY mail_type.name",'ro');$d=[];while($x=mysqli_fetch_row($r))$d[]=[$x[1],(float)$x[0]];echo '<div id="mailchart_div">'.atlas_chart_pie($d,'Mail Types').'</div>';}
